INSERT INTO `wp_comments` VALUES (1,1,'Một người bình luận WordPress','wapuu@wordpress.example','https://vi.wordpress.org/','','2026-09-07 07:30:44','2026-09-07 07:30:44','Xin chào, đây là một bình luận.\nĐể bắt đầu kiểm duyệt, chỉnh sửa và xóa nhận xét, vui lòng truy cập màn hình Nhận xét trong trang quản trị.\nHình đại diện của người bình luận đến từ <a href=\"https://gravatar.com/\">Gravatar</a>.',0,'1','','comment',0,0),(2,1,'ZAP','zaproxy@example.com','https://zap.example.com','127.0.0.1','2026-10-28 23:24:12','2026-10-28 23:24:12','Zaproxy dolore alias impedit expedita quisquam.',0,'0','','comment',0,0);
